        "coreNarrative": "这篇选自文化艺术专栏的深度长文，聚焦于美国最古老的交响乐团——纽约爱乐乐团（New York Philharmonic，创立于1842年）在21世纪的艰难转身。纽约爱乐曾由马勒（Gustav Mahler）、托斯卡尼尼（Toscanini）、伯恩斯坦（Bernstein）、布列兹（Pierre Boulez）等二十世纪无可超越的音乐巨神执掌。然而到了2009年，乐团却出人意料地聘任了年仅42岁、在大众知名度上相对平淡的艾伦·吉尔伯特（Alan Gilbert）。传统古典音乐界固然欣喜于他的‘谦逊不装腔作势（unpretentious）’，但作者敏锐地指出，交响乐团面临的真正灭顶之灾，根本不是选谁当指挥，而是‘数字录音技术（CD与iTunes）对传统实体音乐会的降维打击’。在黄金时代，大师的录音不仅音质完美、价格极度低廉、随时随地戴上耳机即可消费，在艺术水准上更是当今年轻演奏家难以企及的巅峰；面对博物馆、歌剧院、电影与数字媒体的多维竞争，传统音乐会高昂的票价和老态龙钟的仪式感，正在彻底失去年轻一代受众。",
        "theAudienceDilemmaExplained": "吉尔伯特试图通过引入先锋派、未录音的新作品（new music）来吸引眼球，但作者给出了极其冷峻的判词：‘仅仅扩大曲目库是远远不够的’。如果无法从根本上重塑乐团与年轻观众之间的心理连接和审美共鸣（change the relationship with the new audience），任何曲目单上的修修补补，都无法逆转古典音乐会体制整体走向衰竭的历史宿命。",
