        "subtitle": "从‘被挖角神话’到‘无网跳槽’——2008年次贷危机后企业高管职业生态与规则颠覆",
        "coreNarrative": "传统英美商业文化中，企业高管流动遵循‘在位挖角’（poached sitting CEOs）与‘原地留守更稳’（safer to stay where you are）的教条。在过去，高管在未找好下一份工作（without a position lined up）时离职，会被外界视为遭到董事会解雇或能力存疑的‘耻辱’（old disgrace）。然而2008年金融危机之后，股东对董事会施加空前压力，严厉审查接班人计划（succession plans）。企业内部二把手（deputy chiefs / No.2 executives）面临晋升天花板，且原地等待容易为危机时期的坏账与决策背锅（cloud reputations）。以美国银行总裁利亚姆·麦基（Liam McGee）为代表的优秀高管开始选择‘无安全网跳跃’（jump without a net）——主动裸辞并公开宣布统领一家企业的野心。这一打破常规的行为不仅迅速赢得了哈特福德等金融巨头的青睐，更彻底扭转了商界的跳槽逻辑：在危机与动荡中，待得太久的人反而伤得最重。",
        "historicalAndEconomicContext": "2008年金融危机后，美国《多德-弗兰克法案》与股东维权主义兴起，董事会处于聚光灯下。传统‘金色降落伞’与暗箱操作的接班流程受到挑战，企业二号人物若未被相中（don't get the nod），通过公开离职展示自信与独立领导力，反而成为最有效的公关与职业突破路径。",
