        "subtitle": "口碑红利与公关黑天鹅——Web 2.0时代企业如何应对‘被劫持媒体’（Hijacked Media）",
        "coreNarrative": "在传统大众传媒时代，商业营销遵循‘一分钱一分货’（you get what you pay for）的简单法则，企业依靠重金购买电视报刊等‘付费媒体’（paid media）维持知名度。随着互联网与社交网络普及，现代营销学确立了更为立体的 POES 媒体矩阵：包括企业自建运营的‘自有媒体’（owned media）、消费者自发口碑推荐的‘赢得媒体’（earned media）、以及高流量自营平台变现的‘售卖媒体’（sold media）。然而，技术赋予营销人员更多元传播途径的同时，也赋权了‘热情的消费者’。一旦发生产品质量缺陷或道德争议，消费者能通过社交网络迅速将品牌资产转化为‘被劫持媒体’（hijacked media），发起声势浩大的抵制运动。2010年丰田汽车深陷全球召回危机，通过在 Twitter 和 Digg 等前沿社交阵地展开即时直面互动，开创了跨国巨头有效应对被劫持媒体的经典范式。",
        "historicalAndEconomicContext": "文章反映了2009-2010年全球数字营销与Web 2.0从博客向动态社交网络（Twitter, Facebook, Digg）迁移的剧烈转型期。单向灌输式广告效果日薄西山，双向社交互动成为核心资产，但也极大缩短了公关危机的发酵周期，使危机公关学习曲线变得极其陡峭（steep learning curve）。",
